-- =============================================================================
-- ExtrusionMasterUpdateSeed.sql
-- Populates new columns (ApMm, PpMm, PhCode, SubsillTier, ThermalBreakType)
-- in the ExtrusionMaster table. Extracted from Sample.xlsm 'DATA' sheet via openpyxl.
-- Run once by EnsureSchemaExists when ApMm IS NULL (both new and existing installations).
-- =============================================================================

CREATE TABLE #ExtMig (
    Section NVARCHAR(50) NOT NULL,
    ApMm DECIMAL(18,4) NOT NULL DEFAULT 0,
    PpMm DECIMAL(18,4) NOT NULL DEFAULT 0,
    PhCode NVARCHAR(50) NULL,
    SubsillTier INT NOT NULL DEFAULT 0,
    ThermalBreakType NVARCHAR(10) NOT NULL DEFAULT 'No'
);

















UPDATE em SET
    em.ApMm = ISNULL(m.ApMm, 0),
    em.PpMm = ISNULL(m.PpMm, 0),
    em.PhCode = m.PhCode,
    em.SubsillTier = ISNULL(m.SubsillTier, 0),
    em.ThermalBreakType = ISNULL(m.ThermalBreakType, 'No')
FROM ExtrusionMaster em
INNER JOIN #ExtMig m ON em.Section = m.Section;

DROP TABLE #ExtMig;